import{_ as a,o as r,c as n,a2 as o}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"ADR-005: Parallel frame-range workers and segment concatenation","description":"","frontmatter":{},"headers":[],"relativePath":"adr/005-parallel-frame-range-workers.md","filePath":"adr/005-parallel-frame-range-workers.md"}'),t={name:"adr/005-parallel-frame-range-workers.md"};function s(l,e,i,c,d,m){return r(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="adr-005-parallel-frame-range-workers-and-segment-concatenation" tabindex="-1">ADR-005: Parallel frame-range workers and segment concatenation <a class="header-anchor" href="#adr-005-parallel-frame-range-workers-and-segment-concatenation" aria-label="Permalink to &quot;ADR-005: Parallel frame-range workers and segment concatenation&quot;">​</a></h1><ul><li>Status: accepted · Date: 2026-10-15</li></ul><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The frame range is split into N contiguous ranges (default: cores − 1). Each worker owns a Chromium process and an ffmpeg process (<code>image2pipe</code> JPEG → x264 CRF 14 <code>veryfast</code> intermediate). Segments are joined with the concat demuxer (stream copy) and the total frame count is verified. A crashed worker is retried once.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Near-linear scaling with cores; memory stays bounded per worker.</li><li>Separate browsers (not tabs) avoid renderer-process sharing that would serialize work.</li><li>Intermediate segments are visually lossless; the final master/share encodes read them once.</li></ul>',6)])])}const u=a(t,[["render",s]]);export{p as __pageData,u as default};
